void DriverScreenViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &button1)
    {
        //Interaction2
        //When button1 clicked change screen to DataScreen
        //Go to DataScreen with screen transition towards East
        application().gotoDataScreenScreenSlideTransitionEast();
    }
}

void DriverScreenViewBase::handleTickEvent()
{
    frameCountInteraction1Interval++;
    if(frameCountInteraction1Interval == TICK_INTERACTION1_INTERVAL)
    {
        //Interaction1
        //When every N tick call virtual function
        //Call main
        main();
        frameCountInteraction1Interval = 0;
    }
}
